//! The web frontend of the dioxus-workspace test project.

use dioxus::prelude::*;
use ui::Banner;

// regenerated by dx from tailwind.css on every build
const TAILWIND_CSS: Asset = asset!("/assets/tailwind.css");

fn main() {
    dioxus::launch(App);
}

/// The root component, built from the workspace's shared ui crate.
#[component]
fn App() -> Element {
    rsx! {
        document::Stylesheet { href: TAILWIND_CSS }

        main {
            Banner {}
            p { class: "italic", "hello from the web crate" }
        }
    }
}
